      real(dp) :: sy(0:3,0:3)
      real(dp) :: sz(0:3,0:3)
      real(dp) :: mx1(0:0,0:1), my1(0:0,0:1), mz1(0:0,0:1)
      real(dp) :: mx2(0:0,0:1), my2(0:0,0:1), mz2(0:0,0:1)
