         mz2(0,1) = oz*oz*sz(0,1) &
            + 2.0_dp*oz*sz(1,1) &
            + sz(2,1)
         mz3(0,0) = oz*oz*oz*sz(0,0) &
            + 3.0_dp*oz*oz*sz(1,0) &
            + 3.0_dp*oz*sz(2,0) &
            + sz(3,0)
         mz3(0,1) = oz*oz*oz*sz(0,1) &
            + 3.0_dp*oz*oz*sz(1,1) &
            + 3.0_dp*oz*sz(2,1) &
            + sz(3,1)
         mout(1,1) = mout(1,1) + cc*mx1(0,1)*sy(0,0)*sz(0,0)
