         mout(3,12) = mout(3,12) + cc*sx(0,0)*sy(0,0)*mz2(0,1)
         mout(1,13) = mout(1,13) + cc*mx3(0,1)*sy(0,0)*sz(0,0)
         mout(2,13) = mout(2,13) + cc*mx3(0,0)*sy(0,1)*sz(0,0)
         mout(3,13) = mout(3,13) + cc*mx3(0,0)*sy(0,0)*sz(0,1)
         mout(1,14) = mout(1,14) + cc*mx2(0,1)*my1(0,0)*sz(0,0)
         mout(2,14) = mout(2,14) + cc*mx2(0,0)*my1(0,1)*sz(0,0)
