         mout(1,21) = mout(1,21) + cc*mx1(0,1)*sy(0,0)*mz2(0,0)
         mout(2,21) = mout(2,21) + cc*mx1(0,0)*sy(0,1)*mz2(0,0)
         mout(3,21) = mout(3,21) + cc*mx1(0,0)*sy(0,0)*mz2(0,1)
         mout(1,22) = mout(1,22) + cc*mx2(0,1)*my1(0,0)*sz(0,0)
         mout(2,22) = mout(2,22) + cc*mx2(0,0)*my1(0,1)*sz(0,0)
         mout(3,22) = mout(3,22) + cc*mx2(0,0)*my1(0,0)*sz(0,1)
         mout(1,23) = mout(1,23) + cc*mx1(0,1)*my2(0,0)*sz(0,0)
         mout(2,23) = mout(2,23) + cc*mx1(0,0)*my2(0,1)*sz(0,0)
         mout(3,23) = mout(3,23) + cc*mx1(0,0)*my2(0,0)*sz(0,1)
         mout(1,24) = mout(1,24) + cc*mx1(0,1)*my1(0,0)*mz1(0,0)
         mout(2,24) = mout(2,24) + cc*mx1(0,0)*my1(0,1)*mz1(0,0)
         mout(3,24) = mout(3,24) + cc*mx1(0,0)*my1(0,0)*mz1(0,1)
         mout(1,25) = mout(1,25) + cc*mx1(0,1)*my2(0,0)*sz(0,0)
         mout(2,25) = mout(2,25) + cc*mx1(0,0)*my2(0,1)*sz(0,0)
         mout(3,25) = mout(3,25) + cc*mx1(0,0)*my2(0,0)*sz(0,1)
         mout(1,26) = mout(1,26) + cc*sx(0,1)*my3(0,0)*sz(0,0)
         mout(2,26) = mout(2,26) + cc*sx(0,0)*my3(0,1)*sz(0,0)
         mout(3,26) = mout(3,26) + cc*sx(0,0)*my3(0,0)*sz(0,1)
         mout(1,27) = mout(1,27) + cc*sx(0,1)*my2(0,0)*mz1(0,0)
         mout(2,27) = mout(2,27) + cc*sx(0,0)*my2(0,1)*mz1(0,0)
         mout(3,27) = mout(3,27) + cc*sx(0,0)*my2(0,0)*mz1(0,1)
         mout(1,28) = mout(1,28) + cc*mx1(0,1)*my1(0,0)*mz1(0,0)
         mout(2,28) = mout(2,28) + cc*mx1(0,0)*my1(0,1)*mz1(0,0)
         mout(3,28) = mout(3,28) + cc*mx1(0,0)*my1(0,0)*mz1(0,1)
         mout(1,29) = mout(1,29) + cc*sx(0,1)*my2(0,0)*mz1(0,0)
         mout(2,29) = mout(2,29) + cc*sx(0,0)*my2(0,1)*mz1(0,0)
         mout(3,29) = mout(3,29) + cc*sx(0,0)*my2(0,0)*mz1(0,1)
         mout(1,30) = mout(1,30) + cc*sx(0,1)*my1(0,0)*mz2(0,0)
         mout(2,30) = mout(2,30) + cc*sx(0,0)*my1(0,1)*mz2(0,0)
         mout(3,30) = mout(3,30) + cc*sx(0,0)*my1(0,0)*mz2(0,1)
         mout(1,31) = mout(1,31) + cc*mx2(0,1)*sy(0,0)*mz1(0,0)
         mout(2,31) = mout(2,31) + cc*mx2(0,0)*sy(0,1)*mz1(0,0)
         mout(3,31) = mout(3,31) + cc*mx2(0,0)*sy(0,0)*mz1(0,1)
         mout(1,32) = mout(1,32) + cc*mx1(0,1)*my1(0,0)*mz1(0,0)
         mout(2,32) = mout(2,32) + cc*mx1(0,0)*my1(0,1)*mz1(0,0)
         mout(3,32) = mout(3,32) + cc*mx1(0,0)*my1(0,0)*mz1(0,1)
         mout(1,33) = mout(1,33) + cc*mx1(0,1)*sy(0,0)*mz2(0,0)
         mout(2,33) = mout(2,33) + cc*mx1(0,0)*sy(0,1)*mz2(0,0)
         mout(3,33) = mout(3,33) + cc*mx1(0,0)*sy(0,0)*mz2(0,1)
         mout(1,34) = mout(1,34) + cc*mx1(0,1)*my1(0,0)*mz1(0,0)
         mout(2,34) = mout(2,34) + cc*mx1(0,0)*my1(0,1)*mz1(0,0)
         mout(3,34) = mout(3,34) + cc*mx1(0,0)*my1(0,0)*mz1(0,1)
         mout(1,35) = mout(1,35) + cc*sx(0,1)*my2(0,0)*mz1(0,0)
         mout(2,35) = mout(2,35) + cc*sx(0,0)*my2(0,1)*mz1(0,0)
         mout(3,35) = mout(3,35) + cc*sx(0,0)*my2(0,0)*mz1(0,1)
         mout(1,36) = mout(1,36) + cc*sx(0,1)*my1(0,0)*mz2(0,0)
         mout(2,36) = mout(2,36) + cc*sx(0,0)*my1(0,1)*mz2(0,0)
         mout(3,36) = mout(3,36) + cc*sx(0,0)*my1(0,0)*mz2(0,1)
         mout(1,37) = mout(1,37) + cc*mx1(0,1)*sy(0,0)*mz2(0,0)
         mout(2,37) = mout(2,37) + cc*mx1(0,0)*sy(0,1)*mz2(0,0)
         mout(3,37) = mout(3,37) + cc*mx1(0,0)*sy(0,0)*mz2(0,1)
         mout(1,38) = mout(1,38) + cc*sx(0,1)*my1(0,0)*mz2(0,0)
         mout(2,38) = mout(2,38) + cc*sx(0,0)*my1(0,1)*mz2(0,0)
         mout(3,38) = mout(3,38) + cc*sx(0,0)*my1(0,0)*mz2(0,1)
         mout(1,39) = mout(1,39) + cc*sx(0,1)*sy(0,0)*mz3(0,0)
         mout(2,39) = mout(2,39) + cc*sx(0,0)*sy(0,1)*mz3(0,0)
         mout(3,39) = mout(3,39) + cc*sx(0,0)*sy(0,0)*mz3(0,1)
      end do
      end do
   end subroutine mult_01


   pure subroutine mult_02(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                 orig, mout)
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3), orig(3)
      real(dp), intent(out) :: mout(6,39)

      integer  :: ip, jp, k, ic
      real(dp) :: al, bet, zeta, oo2z, xi, cc
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: abx, aby, abz, e0x, e0y, e0z, ox, oy, oz
      real(dp) :: sx(0:3,0:4)
      real(dp) :: sy(0:3,0:4)
      real(dp) :: sz(0:3,0:4)
      real(dp) :: mx1(0:0,0:2), my1(0:0,0:2), mz1(0:0,0:2)
      real(dp) :: mx2(0:0,0:2), my2(0:0,0:2), mz2(0:0,0:2)
      real(dp) :: mx3(0:0,0:2), my3(0:0,0:2), mz3(0:0,0:2)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      ox = ra(1) - orig(1); oy = ra(2) - orig(2); oz = ra(3) - orig(3)

      do ic = 1, 39
         do k = 1, 6
            mout(k, ic) = 0.0_dp
         end do
      end do

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)
         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)
         e0x = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abx*abx)
         e0y = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*aby*aby)
         e0z = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abz*abz)

         sx(0,0) = e0x
         sx(1,0) = pax*sx(0,0)
         sx(2,0) = pax*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(3,0) = pax*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(0,1) = pbx*sx(0,0)
         sx(1,1) = pbx*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(2,1) = pbx*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(3,1) = pbx*sx(3,0) + 3.0_dp*oo2z*sx(2,0)
         sx(0,2) = pbx*sx(0,1) + 1.0_dp*oo2z*sx(0,0)
         sx(1,2) = pbx*sx(1,1) + 1.0_dp*oo2z*sx(0,1) + 1.0_dp*oo2z*sx(1,0)
         sx(2,2) = pbx*sx(2,1) + 2.0_dp*oo2z*sx(1,1) + 1.0_dp*oo2z*sx(2,0)
         sx(3,2) = pbx*sx(3,1) + 3.0_dp*oo2z*sx(2,1) + 1.0_dp*oo2z*sx(3,0)
         sx(0,3) = pbx*sx(0,2) + 2.0_dp*oo2z*sx(0,1)
         sx(1,3) = pbx*sx(1,2) + 1.0_dp*oo2z*sx(0,2) + 2.0_dp*oo2z*sx(1,1)
         sx(2,3) = pbx*sx(2,2) + 2.0_dp*oo2z*sx(1,2) + 2.0_dp*oo2z*sx(2,1)
         sx(3,3) = pbx*sx(3,2) + 3.0_dp*oo2z*sx(2,2) + 2.0_dp*oo2z*sx(3,1)
         sx(0,4) = pbx*sx(0,3) + 3.0_dp*oo2z*sx(0,2)
         sx(1,4) = pbx*sx(1,3) + 1.0_dp*oo2z*sx(0,3) + 3.0_dp*oo2z*sx(1,2)
         sx(2,4) = pbx*sx(2,3) + 2.0_dp*oo2z*sx(1,3) + 3.0_dp*oo2z*sx(2,2)
         sx(3,4) = pbx*sx(3,3) + 3.0_dp*oo2z*sx(2,3) + 3.0_dp*oo2z*sx(3,2)
         sy(0,0) = e0y
         sy(1,0) = pay*sy(0,0)
         sy(2,0) = pay*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(3,0) = pay*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(0,1) = pby*sy(0,0)
         sy(1,1) = pby*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(2,1) = pby*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(3,1) = pby*sy(3,0) + 3.0_dp*oo2z*sy(2,0)
         sy(0,2) = pby*sy(0,1) + 1.0_dp*oo2z*sy(0,0)
         sy(1,2) = pby*sy(1,1) + 1.0_dp*oo2z*sy(0,1) + 1.0_dp*oo2z*sy(1,0)
         sy(2,2) = pby*sy(2,1) + 2.0_dp*oo2z*sy(1,1) + 1.0_dp*oo2z*sy(2,0)
         sy(3,2) = pby*sy(3,1) + 3.0_dp*oo2z*sy(2,1) + 1.0_dp*oo2z*sy(3,0)
         sy(0,3) = pby*sy(0,2) + 2.0_dp*oo2z*sy(0,1)
         sy(1,3) = pby*sy(1,2) + 1.0_dp*oo2z*sy(0,2) + 2.0_dp*oo2z*sy(1,1)
         sy(2,3) = pby*sy(2,2) + 2.0_dp*oo2z*sy(1,2) + 2.0_dp*oo2z*sy(2,1)
         sy(3,3) = pby*sy(3,2) + 3.0_dp*oo2z*sy(2,2) + 2.0_dp*oo2z*sy(3,1)
         sy(0,4) = pby*sy(0,3) + 3.0_dp*oo2z*sy(0,2)
         sy(1,4) = pby*sy(1,3) + 1.0_dp*oo2z*sy(0,3) + 3.0_dp*oo2z*sy(1,2)
         sy(2,4) = pby*sy(2,3) + 2.0_dp*oo2z*sy(1,3) + 3.0_dp*oo2z*sy(2,2)
         sy(3,4) = pby*sy(3,3) + 3.0_dp*oo2z*sy(2,3) + 3.0_dp*oo2z*sy(3,2)
         sz(0,0) = e0z
         sz(1,0) = paz*sz(0,0)
         sz(2,0) = paz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(3,0) = paz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(0,1) = pbz*sz(0,0)
         sz(1,1) = pbz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(2,1) = pbz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(3,1) = pbz*sz(3,0) + 3.0_dp*oo2z*sz(2,0)
         sz(0,2) = pbz*sz(0,1) + 1.0_dp*oo2z*sz(0,0)
         sz(1,2) = pbz*sz(1,1) + 1.0_dp*oo2z*sz(0,1) + 1.0_dp*oo2z*sz(1,0)
         sz(2,2) = pbz*sz(2,1) + 2.0_dp*oo2z*sz(1,1) + 1.0_dp*oo2z*sz(2,0)
         sz(3,2) = pbz*sz(3,1) + 3.0_dp*oo2z*sz(2,1) + 1.0_dp*oo2z*sz(3,0)
         sz(0,3) = pbz*sz(0,2) + 2.0_dp*oo2z*sz(0,1)
