         mout(6,27) = mout(6,27) + cc*sx(0,0)*my2(0,0)*mz1(0,2)
         mout(1,28) = mout(1,28) + cc*mx1(0,2)*my1(0,0)*mz1(0,0)
         mout(2,28) = mout(2,28) + cc*mx1(0,1)*my1(0,1)*mz1(0,0)
         mout(3,28) = mout(3,28) + cc*mx1(0,1)*my1(0,0)*mz1(0,1)
         mout(4,28) = mout(4,28) + cc*mx1(0,0)*my1(0,2)*mz1(0,0)
         mout(5,28) = mout(5,28) + cc*mx1(0,0)*my1(0,1)*mz1(0,1)
         mout(6,28) = mout(6,28) + cc*mx1(0,0)*my1(0,0)*mz1(0,2)
         mout(1,29) = mout(1,29) + cc*sx(0,2)*my2(0,0)*mz1(0,0)
         mout(2,29) = mout(2,29) + cc*sx(0,1)*my2(0,1)*mz1(0,0)
         mout(3,29) = mout(3,29) + cc*sx(0,1)*my2(0,0)*mz1(0,1)
         mout(4,29) = mout(4,29) + cc*sx(0,0)*my2(0,2)*mz1(0,0)
         mout(5,29) = mout(5,29) + cc*sx(0,0)*my2(0,1)*mz1(0,1)
         mout(6,29) = mout(6,29) + cc*sx(0,0)*my2(0,0)*mz1(0,2)
         mout(1,30) = mout(1,30) + cc*sx(0,2)*my1(0,0)*mz2(0,0)
         mout(2,30) = mout(2,30) + cc*sx(0,1)*my1(0,1)*mz2(0,0)
         mout(3,30) = mout(3,30) + cc*sx(0,1)*my1(0,0)*mz2(0,1)
         mout(4,30) = mout(4,30) + cc*sx(0,0)*my1(0,2)*mz2(0,0)
         mout(5,30) = mout(5,30) + cc*sx(0,0)*my1(0,1)*mz2(0,1)
         mout(6,30) = mout(6,30) + cc*sx(0,0)*my1(0,0)*mz2(0,2)
         mout(1,31) = mout(1,31) + cc*mx2(0,2)*sy(0,0)*mz1(0,0)
         mout(2,31) = mout(2,31) + cc*mx2(0,1)*sy(0,1)*mz1(0,0)
         mout(3,31) = mout(3,31) + cc*mx2(0,1)*sy(0,0)*mz1(0,1)
         mout(4,31) = mout(4,31) + cc*mx2(0,0)*sy(0,2)*mz1(0,0)
         mout(5,31) = mout(5,31) + cc*mx2(0,0)*sy(0,1)*mz1(0,1)
         mout(6,31) = mout(6,31) + cc*mx2(0,0)*sy(0,0)*mz1(0,2)
         mout(1,32) = mout(1,32) + cc*mx1(0,2)*my1(0,0)*mz1(0,0)
         mout(2,32) = mout(2,32) + cc*mx1(0,1)*my1(0,1)*mz1(0,0)
         mout(3,32) = mout(3,32) + cc*mx1(0,1)*my1(0,0)*mz1(0,1)
         mout(4,32) = mout(4,32) + cc*mx1(0,0)*my1(0,2)*mz1(0,0)
         mout(5,32) = mout(5,32) + cc*mx1(0,0)*my1(0,1)*mz1(0,1)
         mout(6,32) = mout(6,32) + cc*mx1(0,0)*my1(0,0)*mz1(0,2)
         mout(1,33) = mout(1,33) + cc*mx1(0,2)*sy(0,0)*mz2(0,0)
         mout(2,33) = mout(2,33) + cc*mx1(0,1)*sy(0,1)*mz2(0,0)
         mout(3,33) = mout(3,33) + cc*mx1(0,1)*sy(0,0)*mz2(0,1)
         mout(4,33) = mout(4,33) + cc*mx1(0,0)*sy(0,2)*mz2(0,0)
         mout(5,33) = mout(5,33) + cc*mx1(0,0)*sy(0,1)*mz2(0,1)
         mout(6,33) = mout(6,33) + cc*mx1(0,0)*sy(0,0)*mz2(0,2)
         mout(1,34) = mout(1,34) + cc*mx1(0,2)*my1(0,0)*mz1(0,0)
         mout(2,34) = mout(2,34) + cc*mx1(0,1)*my1(0,1)*mz1(0,0)
         mout(3,34) = mout(3,34) + cc*mx1(0,1)*my1(0,0)*mz1(0,1)
         mout(4,34) = mout(4,34) + cc*mx1(0,0)*my1(0,2)*mz1(0,0)
         mout(5,34) = mout(5,34) + cc*mx1(0,0)*my1(0,1)*mz1(0,1)
         mout(6,34) = mout(6,34) + cc*mx1(0,0)*my1(0,0)*mz1(0,2)
         mout(1,35) = mout(1,35) + cc*sx(0,2)*my2(0,0)*mz1(0,0)
         mout(2,35) = mout(2,35) + cc*sx(0,1)*my2(0,1)*mz1(0,0)
         mout(3,35) = mout(3,35) + cc*sx(0,1)*my2(0,0)*mz1(0,1)
         mout(4,35) = mout(4,35) + cc*sx(0,0)*my2(0,2)*mz1(0,0)
         mout(5,35) = mout(5,35) + cc*sx(0,0)*my2(0,1)*mz1(0,1)
         mout(6,35) = mout(6,35) + cc*sx(0,0)*my2(0,0)*mz1(0,2)
         mout(1,36) = mout(1,36) + cc*sx(0,2)*my1(0,0)*mz2(0,0)
         mout(2,36) = mout(2,36) + cc*sx(0,1)*my1(0,1)*mz2(0,0)
         mout(3,36) = mout(3,36) + cc*sx(0,1)*my1(0,0)*mz2(0,1)
         mout(4,36) = mout(4,36) + cc*sx(0,0)*my1(0,2)*mz2(0,0)
         mout(5,36) = mout(5,36) + cc*sx(0,0)*my1(0,1)*mz2(0,1)
         mout(6,36) = mout(6,36) + cc*sx(0,0)*my1(0,0)*mz2(0,2)
         mout(1,37) = mout(1,37) + cc*mx1(0,2)*sy(0,0)*mz2(0,0)
         mout(2,37) = mout(2,37) + cc*mx1(0,1)*sy(0,1)*mz2(0,0)
         mout(3,37) = mout(3,37) + cc*mx1(0,1)*sy(0,0)*mz2(0,1)
         mout(4,37) = mout(4,37) + cc*mx1(0,0)*sy(0,2)*mz2(0,0)
         mout(5,37) = mout(5,37) + cc*mx1(0,0)*sy(0,1)*mz2(0,1)
         mout(6,37) = mout(6,37) + cc*mx1(0,0)*sy(0,0)*mz2(0,2)
         mout(1,38) = mout(1,38) + cc*sx(0,2)*my1(0,0)*mz2(0,0)
         mout(2,38) = mout(2,38) + cc*sx(0,1)*my1(0,1)*mz2(0,0)
         mout(3,38) = mout(3,38) + cc*sx(0,1)*my1(0,0)*mz2(0,1)
         mout(4,38) = mout(4,38) + cc*sx(0,0)*my1(0,2)*mz2(0,0)
         mout(5,38) = mout(5,38) + cc*sx(0,0)*my1(0,1)*mz2(0,1)
         mout(6,38) = mout(6,38) + cc*sx(0,0)*my1(0,0)*mz2(0,2)
         mout(1,39) = mout(1,39) + cc*sx(0,2)*sy(0,0)*mz3(0,0)
         mout(2,39) = mout(2,39) + cc*sx(0,1)*sy(0,1)*mz3(0,0)
         mout(3,39) = mout(3,39) + cc*sx(0,1)*sy(0,0)*mz3(0,1)
         mout(4,39) = mout(4,39) + cc*sx(0,0)*sy(0,2)*mz3(0,0)
         mout(5,39) = mout(5,39) + cc*sx(0,0)*sy(0,1)*mz3(0,1)
         mout(6,39) = mout(6,39) + cc*sx(0,0)*sy(0,0)*mz3(0,2)
      end do
      end do
   end subroutine mult_02


   pure subroutine mult_10(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                 orig, mout)
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3), orig(3)
      real(dp), intent(out) :: mout(3,39)

      integer  :: ip, jp, k, ic
      real(dp) :: al, bet, zeta, oo2z, xi, cc
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: abx, aby, abz, e0x, e0y, e0z, ox, oy, oz
      real(dp) :: sx(0:4,0:2)
      real(dp) :: sy(0:4,0:2)
      real(dp) :: sz(0:4,0:2)
      real(dp) :: mx1(0:1,0:0), my1(0:1,0:0), mz1(0:1,0:0)
      real(dp) :: mx2(0:1,0:0), my2(0:1,0:0), mz2(0:1,0:0)
      real(dp) :: mx3(0:1,0:0), my3(0:1,0:0), mz3(0:1,0:0)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      ox = ra(1) - orig(1); oy = ra(2) - orig(2); oz = ra(3) - orig(3)

      do ic = 1, 39
         do k = 1, 3
            mout(k, ic) = 0.0_dp
         end do
      end do

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)
         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)
         e0x = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abx*abx)
         e0y = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*aby*aby)
         e0z = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abz*abz)

         sx(0,0) = e0x
         sx(1,0) = pax*sx(0,0)
         sx(2,0) = pax*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(3,0) = pax*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(4,0) = pax*sx(3,0) + 3.0_dp*oo2z*sx(2,0)
         sx(0,1) = pbx*sx(0,0)
         sx(1,1) = pbx*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(2,1) = pbx*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(3,1) = pbx*sx(3,0) + 3.0_dp*oo2z*sx(2,0)
         sx(4,1) = pbx*sx(4,0) + 4.0_dp*oo2z*sx(3,0)
         sx(0,2) = pbx*sx(0,1) + 1.0_dp*oo2z*sx(0,0)
         sx(1,2) = pbx*sx(1,1) + 1.0_dp*oo2z*sx(0,1) + 1.0_dp*oo2z*sx(1,0)
         sx(2,2) = pbx*sx(2,1) + 2.0_dp*oo2z*sx(1,1) + 1.0_dp*oo2z*sx(2,0)
         sx(3,2) = pbx*sx(3,1) + 3.0_dp*oo2z*sx(2,1) + 1.0_dp*oo2z*sx(3,0)
         sx(4,2) = pbx*sx(4,1) + 4.0_dp*oo2z*sx(3,1) + 1.0_dp*oo2z*sx(4,0)
         sy(0,0) = e0y
         sy(1,0) = pay*sy(0,0)
         sy(2,0) = pay*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(3,0) = pay*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(4,0) = pay*sy(3,0) + 3.0_dp*oo2z*sy(2,0)
         sy(0,1) = pby*sy(0,0)
         sy(1,1) = pby*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(2,1) = pby*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(3,1) = pby*sy(3,0) + 3.0_dp*oo2z*sy(2,0)
         sy(4,1) = pby*sy(4,0) + 4.0_dp*oo2z*sy(3,0)
         sy(0,2) = pby*sy(0,1) + 1.0_dp*oo2z*sy(0,0)
         sy(1,2) = pby*sy(1,1) + 1.0_dp*oo2z*sy(0,1) + 1.0_dp*oo2z*sy(1,0)
         sy(2,2) = pby*sy(2,1) + 2.0_dp*oo2z*sy(1,1) + 1.0_dp*oo2z*sy(2,0)
         sy(3,2) = pby*sy(3,1) + 3.0_dp*oo2z*sy(2,1) + 1.0_dp*oo2z*sy(3,0)
         sy(4,2) = pby*sy(4,1) + 4.0_dp*oo2z*sy(3,1) + 1.0_dp*oo2z*sy(4,0)
         sz(0,0) = e0z
         sz(1,0) = paz*sz(0,0)
         sz(2,0) = paz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(3,0) = paz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(4,0) = paz*sz(3,0) + 3.0_dp*oo2z*sz(2,0)
         sz(0,1) = pbz*sz(0,0)
         sz(1,1) = pbz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(2,1) = pbz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(3,1) = pbz*sz(3,0) + 3.0_dp*oo2z*sz(2,0)
         sz(4,1) = pbz*sz(4,0) + 4.0_dp*oo2z*sz(3,0)
         sz(0,2) = pbz*sz(0,1) + 1.0_dp*oo2z*sz(0,0)
         sz(1,2) = pbz*sz(1,1) + 1.0_dp*oo2z*sz(0,1) + 1.0_dp*oo2z*sz(1,0)
         sz(2,2) = pbz*sz(2,1) + 2.0_dp*oo2z*sz(1,1) + 1.0_dp*oo2z*sz(2,0)
         sz(3,2) = pbz*sz(3,1) + 3.0_dp*oo2z*sz(2,1) + 1.0_dp*oo2z*sz(3,0)
         sz(4,2) = pbz*sz(4,1) + 4.0_dp*oo2z*sz(3,1) + 1.0_dp*oo2z*sz(4,0)

         mx1(0,0) = ox*sx(0,0) &
            + sx(1,0)
         mx1(1,0) = ox*sx(1,0) &
            + sx(2,0)
         mx2(0,0) = ox*ox*sx(0,0) &
            + 2.0_dp*ox*sx(1,0) &
            + sx(2,0)
         mx2(1,0) = ox*ox*sx(1,0) &
            + 2.0_dp*ox*sx(2,0) &
            + sx(3,0)
         mx3(0,0) = ox*ox*ox*sx(0,0) &
            + 3.0_dp*ox*ox*sx(1,0) &
            + 3.0_dp*ox*sx(2,0) &
            + sx(3,0)
         mx3(1,0) = ox*ox*ox*sx(1,0) &
            + 3.0_dp*ox*ox*sx(2,0) &
            + 3.0_dp*ox*sx(3,0) &
            + sx(4,0)
         my1(0,0) = oy*sy(0,0) &
            + sy(1,0)
         my1(1,0) = oy*sy(1,0) &
            + sy(2,0)
         my2(0,0) = oy*oy*sy(0,0) &
            + 2.0_dp*oy*sy(1,0) &
            + sy(2,0)
         my2(1,0) = oy*oy*sy(1,0) &
            + 2.0_dp*oy*sy(2,0) &
            + sy(3,0)
         my3(0,0) = oy*oy*oy*sy(0,0) &
            + 3.0_dp*oy*oy*sy(1,0) &
            + 3.0_dp*oy*sy(2,0) &
            + sy(3,0)
         my3(1,0) = oy*oy*oy*sy(1,0) &
            + 3.0_dp*oy*oy*sy(2,0) &
            + 3.0_dp*oy*sy(3,0) &
            + sy(4,0)
         mz1(0,0) = oz*sz(0,0) &
            + sz(1,0)
         mz1(1,0) = oz*sz(1,0) &
            + sz(2,0)
         mz2(0,0) = oz*oz*sz(0,0) &
            + 2.0_dp*oz*sz(1,0) &
            + sz(2,0)
         mz2(1,0) = oz*oz*sz(1,0) &
            + 2.0_dp*oz*sz(2,0) &
            + sz(3,0)
         mz3(0,0) = oz*oz*oz*sz(0,0) &
            + 3.0_dp*oz*oz*sz(1,0) &
            + 3.0_dp*oz*sz(2,0) &
            + sz(3,0)
         mz3(1,0) = oz*oz*oz*sz(1,0) &
            + 3.0_dp*oz*oz*sz(2,0) &
            + 3.0_dp*oz*sz(3,0) &
            + sz(4,0)
         mout(1,1) = mout(1,1) + cc*mx1(1,0)*sy(0,0)*sz(0,0)
         mout(2,1) = mout(2,1) + cc*mx1(0,0)*sy(1,0)*sz(0,0)
         mout(3,1) = mout(3,1) + cc*mx1(0,0)*sy(0,0)*sz(1,0)
         mout(1,2) = mout(1,2) + cc*sx(1,0)*my1(0,0)*sz(0,0)
         mout(2,2) = mout(2,2) + cc*sx(0,0)*my1(1,0)*sz(0,0)
         mout(3,2) = mout(3,2) + cc*sx(0,0)*my1(0,0)*sz(1,0)
         mout(1,3) = mout(1,3) + cc*sx(1,0)*sy(0,0)*mz1(0,0)
         mout(2,3) = mout(2,3) + cc*sx(0,0)*sy(1,0)*mz1(0,0)
         mout(3,3) = mout(3,3) + cc*sx(0,0)*sy(0,0)*mz1(1,0)
         mout(1,4) = mout(1,4) + cc*mx2(1,0)*sy(0,0)*sz(0,0)
         mout(2,4) = mout(2,4) + cc*mx2(0,0)*sy(1,0)*sz(0,0)
         mout(3,4) = mout(3,4) + cc*mx2(0,0)*sy(0,0)*sz(1,0)
         mout(1,5) = mout(1,5) + cc*mx1(1,0)*my1(0,0)*sz(0,0)
         mout(2,5) = mout(2,5) + cc*mx1(0,0)*my1(1,0)*sz(0,0)
         mout(3,5) = mout(3,5) + cc*mx1(0,0)*my1(0,0)*sz(1,0)
         mout(1,6) = mout(1,6) + cc*mx1(1,0)*sy(0,0)*mz1(0,0)
         mout(2,6) = mout(2,6) + cc*mx1(0,0)*sy(1,0)*mz1(0,0)
         mout(3,6) = mout(3,6) + cc*mx1(0,0)*sy(0,0)*mz1(1,0)
         mout(1,7) = mout(1,7) + cc*mx1(1,0)*my1(0,0)*sz(0,0)
         mout(2,7) = mout(2,7) + cc*mx1(0,0)*my1(1,0)*sz(0,0)
         mout(3,7) = mout(3,7) + cc*mx1(0,0)*my1(0,0)*sz(1,0)
         mout(1,8) = mout(1,8) + cc*sx(1,0)*my2(0,0)*sz(0,0)
         mout(2,8) = mout(2,8) + cc*sx(0,0)*my2(1,0)*sz(0,0)
         mout(3,8) = mout(3,8) + cc*sx(0,0)*my2(0,0)*sz(1,0)
         mout(1,9) = mout(1,9) + cc*sx(1,0)*my1(0,0)*mz1(0,0)
         mout(2,9) = mout(2,9) + cc*sx(0,0)*my1(1,0)*mz1(0,0)
         mout(3,9) = mout(3,9) + cc*sx(0,0)*my1(0,0)*mz1(1,0)
         mout(1,10) = mout(1,10) + cc*mx1(1,0)*sy(0,0)*mz1(0,0)
         mout(2,10) = mout(2,10) + cc*mx1(0,0)*sy(1,0)*mz1(0,0)
         mout(3,10) = mout(3,10) + cc*mx1(0,0)*sy(0,0)*mz1(1,0)
         mout(1,11) = mout(1,11) + cc*sx(1,0)*my1(0,0)*mz1(0,0)
         mout(2,11) = mout(2,11) + cc*sx(0,0)*my1(1,0)*mz1(0,0)
         mout(3,11) = mout(3,11) + cc*sx(0,0)*my1(0,0)*mz1(1,0)
         mout(1,12) = mout(1,12) + cc*sx(1,0)*sy(0,0)*mz2(0,0)
         mout(2,12) = mout(2,12) + cc*sx(0,0)*sy(1,0)*mz2(0,0)
         mout(3,12) = mout(3,12) + cc*sx(0,0)*sy(0,0)*mz2(1,0)
         mout(1,13) = mout(1,13) + cc*mx3(1,0)*sy(0,0)*sz(0,0)
         mout(2,13) = mout(2,13) + cc*mx3(0,0)*sy(1,0)*sz(0,0)
         mout(3,13) = mout(3,13) + cc*mx3(0,0)*sy(0,0)*sz(1,0)
         mout(1,14) = mout(1,14) + cc*mx2(1,0)*my1(0,0)*sz(0,0)
         mout(2,14) = mout(2,14) + cc*mx2(0,0)*my1(1,0)*sz(0,0)
         mout(3,14) = mout(3,14) + cc*mx2(0,0)*my1(0,0)*sz(1,0)
         mout(1,15) = mout(1,15) + cc*mx2(1,0)*sy(0,0)*mz1(0,0)
         mout(2,15) = mout(2,15) + cc*mx2(0,0)*sy(1,0)*mz1(0,0)
         mout(3,15) = mout(3,15) + cc*mx2(0,0)*sy(0,0)*mz1(1,0)
         mout(1,16) = mout(1,16) + cc*mx2(1,0)*my1(0,0)*sz(0,0)
         mout(2,16) = mout(2,16) + cc*mx2(0,0)*my1(1,0)*sz(0,0)
         mout(3,16) = mout(3,16) + cc*mx2(0,0)*my1(0,0)*sz(1,0)
         mout(1,17) = mout(1,17) + cc*mx1(1,0)*my2(0,0)*sz(0,0)
         mout(2,17) = mout(2,17) + cc*mx1(0,0)*my2(1,0)*sz(0,0)
         mout(3,17) = mout(3,17) + cc*mx1(0,0)*my2(0,0)*sz(1,0)
         mout(1,18) = mout(1,18) + cc*mx1(1,0)*my1(0,0)*mz1(0,0)
         mout(2,18) = mout(2,18) + cc*mx1(0,0)*my1(1,0)*mz1(0,0)
         mout(3,18) = mout(3,18) + cc*mx1(0,0)*my1(0,0)*mz1(1,0)
         mout(1,19) = mout(1,19) + cc*mx2(1,0)*sy(0,0)*mz1(0,0)
         mout(2,19) = mout(2,19) + cc*mx2(0,0)*sy(1,0)*mz1(0,0)
         mout(3,19) = mout(3,19) + cc*mx2(0,0)*sy(0,0)*mz1(1,0)
         mout(1,20) = mout(1,20) + cc*mx1(1,0)*my1(0,0)*mz1(0,0)
         mout(2,20) = mout(2,20) + cc*mx1(0,0)*my1(1,0)*mz1(0,0)
         mout(3,20) = mout(3,20) + cc*mx1(0,0)*my1(0,0)*mz1(1,0)
         mout(1,21) = mout(1,21) + cc*mx1(1,0)*sy(0,0)*mz2(0,0)
         mout(2,21) = mout(2,21) + cc*mx1(0,0)*sy(1,0)*mz2(0,0)
         mout(3,21) = mout(3,21) + cc*mx1(0,0)*sy(0,0)*mz2(1,0)
         mout(1,22) = mout(1,22) + cc*mx2(1,0)*my1(0,0)*sz(0,0)
         mout(2,22) = mout(2,22) + cc*mx2(0,0)*my1(1,0)*sz(0,0)
         mout(3,22) = mout(3,22) + cc*mx2(0,0)*my1(0,0)*sz(1,0)
         mout(1,23) = mout(1,23) + cc*mx1(1,0)*my2(0,0)*sz(0,0)
         mout(2,23) = mout(2,23) + cc*mx1(0,0)*my2(1,0)*sz(0,0)
         mout(3,23) = mout(3,23) + cc*mx1(0,0)*my2(0,0)*sz(1,0)
         mout(1,24) = mout(1,24) + cc*mx1(1,0)*my1(0,0)*mz1(0,0)
         mout(2,24) = mout(2,24) + cc*mx1(0,0)*my1(1,0)*mz1(0,0)
         mout(3,24) = mout(3,24) + cc*mx1(0,0)*my1(0,0)*mz1(1,0)
         mout(1,25) = mout(1,25) + cc*mx1(1,0)*my2(0,0)*sz(0,0)
         mout(2,25) = mout(2,25) + cc*mx1(0,0)*my2(1,0)*sz(0,0)
         mout(3,25) = mout(3,25) + cc*mx1(0,0)*my2(0,0)*sz(1,0)
         mout(1,26) = mout(1,26) + cc*sx(1,0)*my3(0,0)*sz(0,0)
         mout(2,26) = mout(2,26) + cc*sx(0,0)*my3(1,0)*sz(0,0)
         mout(3,26) = mout(3,26) + cc*sx(0,0)*my3(0,0)*sz(1,0)
         mout(1,27) = mout(1,27) + cc*sx(1,0)*my2(0,0)*mz1(0,0)
         mout(2,27) = mout(2,27) + cc*sx(0,0)*my2(1,0)*mz1(0,0)
         mout(3,27) = mout(3,27) + cc*sx(0,0)*my2(0,0)*mz1(1,0)
         mout(1,28) = mout(1,28) + cc*mx1(1,0)*my1(0,0)*mz1(0,0)
         mout(2,28) = mout(2,28) + cc*mx1(0,0)*my1(1,0)*mz1(0,0)
         mout(3,28) = mout(3,28) + cc*mx1(0,0)*my1(0,0)*mz1(1,0)
         mout(1,29) = mout(1,29) + cc*sx(1,0)*my2(0,0)*mz1(0,0)
         mout(2,29) = mout(2,29) + cc*sx(0,0)*my2(1,0)*mz1(0,0)
         mout(3,29) = mout(3,29) + cc*sx(0,0)*my2(0,0)*mz1(1,0)
         mout(1,30) = mout(1,30) + cc*sx(1,0)*my1(0,0)*mz2(0,0)
         mout(2,30) = mout(2,30) + cc*sx(0,0)*my1(1,0)*mz2(0,0)
         mout(3,30) = mout(3,30) + cc*sx(0,0)*my1(0,0)*mz2(1,0)
         mout(1,31) = mout(1,31) + cc*mx2(1,0)*sy(0,0)*mz1(0,0)
         mout(2,31) = mout(2,31) + cc*mx2(0,0)*sy(1,0)*mz1(0,0)
         mout(3,31) = mout(3,31) + cc*mx2(0,0)*sy(0,0)*mz1(1,0)
         mout(1,32) = mout(1,32) + cc*mx1(1,0)*my1(0,0)*mz1(0,0)
         mout(2,32) = mout(2,32) + cc*mx1(0,0)*my1(1,0)*mz1(0,0)
         mout(3,32) = mout(3,32) + cc*mx1(0,0)*my1(0,0)*mz1(1,0)
         mout(1,33) = mout(1,33) + cc*mx1(1,0)*sy(0,0)*mz2(0,0)
         mout(2,33) = mout(2,33) + cc*mx1(0,0)*sy(1,0)*mz2(0,0)
         mout(3,33) = mout(3,33) + cc*mx1(0,0)*sy(0,0)*mz2(1,0)
         mout(1,34) = mout(1,34) + cc*mx1(1,0)*my1(0,0)*mz1(0,0)
         mout(2,34) = mout(2,34) + cc*mx1(0,0)*my1(1,0)*mz1(0,0)
         mout(3,34) = mout(3,34) + cc*mx1(0,0)*my1(0,0)*mz1(1,0)
         mout(1,35) = mout(1,35) + cc*sx(1,0)*my2(0,0)*mz1(0,0)
         mout(2,35) = mout(2,35) + cc*sx(0,0)*my2(1,0)*mz1(0,0)
         mout(3,35) = mout(3,35) + cc*sx(0,0)*my2(0,0)*mz1(1,0)
         mout(1,36) = mout(1,36) + cc*sx(1,0)*my1(0,0)*mz2(0,0)
         mout(2,36) = mout(2,36) + cc*sx(0,0)*my1(1,0)*mz2(0,0)
         mout(3,36) = mout(3,36) + cc*sx(0,0)*my1(0,0)*mz2(1,0)
         mout(1,37) = mout(1,37) + cc*mx1(1,0)*sy(0,0)*mz2(0,0)
         mout(2,37) = mout(2,37) + cc*mx1(0,0)*sy(1,0)*mz2(0,0)
         mout(3,37) = mout(3,37) + cc*mx1(0,0)*sy(0,0)*mz2(1,0)
         mout(1,38) = mout(1,38) + cc*sx(1,0)*my1(0,0)*mz2(0,0)
         mout(2,38) = mout(2,38) + cc*sx(0,0)*my1(1,0)*mz2(0,0)
         mout(3,38) = mout(3,38) + cc*sx(0,0)*my1(0,0)*mz2(1,0)
         mout(1,39) = mout(1,39) + cc*sx(1,0)*sy(0,0)*mz3(0,0)
         mout(2,39) = mout(2,39) + cc*sx(0,0)*sy(1,0)*mz3(0,0)
         mout(3,39) = mout(3,39) + cc*sx(0,0)*sy(0,0)*mz3(1,0)
      end do
      end do
   end subroutine mult_10


   pure subroutine mult_11(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                 orig, mout)
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3), orig(3)
      real(dp), intent(out) :: mout(9,39)

      integer  :: ip, jp, k, ic
      real(dp) :: al, bet, zeta, oo2z, xi, cc
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: abx, aby, abz, e0x, e0y, e0z, ox, oy, oz
      real(dp) :: sx(0:4,0:3)
      real(dp) :: sy(0:4,0:3)
      real(dp) :: sz(0:4,0:3)
      real(dp) :: mx1(0:1,0:1), my1(0:1,0:1), mz1(0:1,0:1)
      real(dp) :: mx2(0:1,0:1), my2(0:1,0:1), mz2(0:1,0:1)
      real(dp) :: mx3(0:1,0:1), my3(0:1,0:1), mz3(0:1,0:1)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      ox = ra(1) - orig(1); oy = ra(2) - orig(2); oz = ra(3) - orig(3)

      do ic = 1, 39
         do k = 1, 9
            mout(k, ic) = 0.0_dp
         end do
      end do

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)
         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)
         e0x = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abx*abx)
         e0y = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*aby*aby)
         e0z = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abz*abz)

         sx(0,0) = e0x
         sx(1,0) = pax*sx(0,0)
         sx(2,0) = pax*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(3,0) = pax*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(4,0) = pax*sx(3,0) + 3.0_dp*oo2z*sx(2,0)
         sx(0,1) = pbx*sx(0,0)
         sx(1,1) = pbx*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(2,1) = pbx*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(3,1) = pbx*sx(3,0) + 3.0_dp*oo2z*sx(2,0)
         sx(4,1) = pbx*sx(4,0) + 4.0_dp*oo2z*sx(3,0)
         sx(0,2) = pbx*sx(0,1) + 1.0_dp*oo2z*sx(0,0)
         sx(1,2) = pbx*sx(1,1) + 1.0_dp*oo2z*sx(0,1) + 1.0_dp*oo2z*sx(1,0)
         sx(2,2) = pbx*sx(2,1) + 2.0_dp*oo2z*sx(1,1) + 1.0_dp*oo2z*sx(2,0)
         sx(3,2) = pbx*sx(3,1) + 3.0_dp*oo2z*sx(2,1) + 1.0_dp*oo2z*sx(3,0)
         sx(4,2) = pbx*sx(4,1) + 4.0_dp*oo2z*sx(3,1) + 1.0_dp*oo2z*sx(4,0)
         sx(0,3) = pbx*sx(0,2) + 2.0_dp*oo2z*sx(0,1)
         sx(1,3) = pbx*sx(1,2) + 1.0_dp*oo2z*sx(0,2) + 2.0_dp*oo2z*sx(1,1)
         sx(2,3) = pbx*sx(2,2) + 2.0_dp*oo2z*sx(1,2) + 2.0_dp*oo2z*sx(2,1)
         sx(3,3) = pbx*sx(3,2) + 3.0_dp*oo2z*sx(2,2) + 2.0_dp*oo2z*sx(3,1)
         sx(4,3) = pbx*sx(4,2) + 4.0_dp*oo2z*sx(3,2) + 2.0_dp*oo2z*sx(4,1)
         sy(0,0) = e0y
         sy(1,0) = pay*sy(0,0)
         sy(2,0) = pay*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(3,0) = pay*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(4,0) = pay*sy(3,0) + 3.0_dp*oo2z*sy(2,0)
         sy(0,1) = pby*sy(0,0)
         sy(1,1) = pby*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(2,1) = pby*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(3,1) = pby*sy(3,0) + 3.0_dp*oo2z*sy(2,0)
         sy(4,1) = pby*sy(4,0) + 4.0_dp*oo2z*sy(3,0)
         sy(0,2) = pby*sy(0,1) + 1.0_dp*oo2z*sy(0,0)
         sy(1,2) = pby*sy(1,1) + 1.0_dp*oo2z*sy(0,1) + 1.0_dp*oo2z*sy(1,0)
         sy(2,2) = pby*sy(2,1) + 2.0_dp*oo2z*sy(1,1) + 1.0_dp*oo2z*sy(2,0)
         sy(3,2) = pby*sy(3,1) + 3.0_dp*oo2z*sy(2,1) + 1.0_dp*oo2z*sy(3,0)
         sy(4,2) = pby*sy(4,1) + 4.0_dp*oo2z*sy(3,1) + 1.0_dp*oo2z*sy(4,0)
         sy(0,3) = pby*sy(0,2) + 2.0_dp*oo2z*sy(0,1)
         sy(1,3) = pby*sy(1,2) + 1.0_dp*oo2z*sy(0,2) + 2.0_dp*oo2z*sy(1,1)
         sy(2,3) = pby*sy(2,2) + 2.0_dp*oo2z*sy(1,2) + 2.0_dp*oo2z*sy(2,1)
         sy(3,3) = pby*sy(3,2) + 3.0_dp*oo2z*sy(2,2) + 2.0_dp*oo2z*sy(3,1)
         sy(4,3) = pby*sy(4,2) + 4.0_dp*oo2z*sy(3,2) + 2.0_dp*oo2z*sy(4,1)
         sz(0,0) = e0z
         sz(1,0) = paz*sz(0,0)
         sz(2,0) = paz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(3,0) = paz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(4,0) = paz*sz(3,0) + 3.0_dp*oo2z*sz(2,0)
         sz(0,1) = pbz*sz(0,0)
         sz(1,1) = pbz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(2,1) = pbz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(3,1) = pbz*sz(3,0) + 3.0_dp*oo2z*sz(2,0)
         sz(4,1) = pbz*sz(4,0) + 4.0_dp*oo2z*sz(3,0)
         sz(0,2) = pbz*sz(0,1) + 1.0_dp*oo2z*sz(0,0)
         sz(1,2) = pbz*sz(1,1) + 1.0_dp*oo2z*sz(0,1) + 1.0_dp*oo2z*sz(1,0)
         sz(2,2) = pbz*sz(2,1) + 2.0_dp*oo2z*sz(1,1) + 1.0_dp*oo2z*sz(2,0)
         sz(3,2) = pbz*sz(3,1) + 3.0_dp*oo2z*sz(2,1) + 1.0_dp*oo2z*sz(3,0)
         sz(4,2) = pbz*sz(4,1) + 4.0_dp*oo2z*sz(3,1) + 1.0_dp*oo2z*sz(4,0)
         sz(0,3) = pbz*sz(0,2) + 2.0_dp*oo2z*sz(0,1)
         sz(1,3) = pbz*sz(1,2) + 1.0_dp*oo2z*sz(0,2) + 2.0_dp*oo2z*sz(1,1)
         sz(2,3) = pbz*sz(2,2) + 2.0_dp*oo2z*sz(1,2) + 2.0_dp*oo2z*sz(2,1)
         sz(3,3) = pbz*sz(3,2) + 3.0_dp*oo2z*sz(2,2) + 2.0_dp*oo2z*sz(3,1)
         sz(4,3) = pbz*sz(4,2) + 4.0_dp*oo2z*sz(3,2) + 2.0_dp*oo2z*sz(4,1)

         mx1(0,0) = ox*sx(0,0) &
            + sx(1,0)
         mx1(1,0) = ox*sx(1,0) &
            + sx(2,0)
         mx1(0,1) = ox*sx(0,1) &
            + sx(1,1)
         mx1(1,1) = ox*sx(1,1) &
            + sx(2,1)
         mx2(0,0) = ox*ox*sx(0,0) &
            + 2.0_dp*ox*sx(1,0) &
            + sx(2,0)
         mx2(1,0) = ox*ox*sx(1,0) &
            + 2.0_dp*ox*sx(2,0) &
            + sx(3,0)
         mx2(0,1) = ox*ox*sx(0,1) &
            + 2.0_dp*ox*sx(1,1) &
            + sx(2,1)
         mx2(1,1) = ox*ox*sx(1,1) &
            + 2.0_dp*ox*sx(2,1) &
            + sx(3,1)
         mx3(0,0) = ox*ox*ox*sx(0,0) &
            + 3.0_dp*ox*ox*sx(1,0) &
            + 3.0_dp*ox*sx(2,0) &
            + sx(3,0)
         mx3(1,0) = ox*ox*ox*sx(1,0) &
            + 3.0_dp*ox*ox*sx(2,0) &
            + 3.0_dp*ox*sx(3,0) &
            + sx(4,0)
         mx3(0,1) = ox*ox*ox*sx(0,1) &
            + 3.0_dp*ox*ox*sx(1,1) &
            + 3.0_dp*ox*sx(2,1) &
            + sx(3,1)
         mx3(1,1) = ox*ox*ox*sx(1,1) &
            + 3.0_dp*ox*ox*sx(2,1) &
            + 3.0_dp*ox*sx(3,1) &
            + sx(4,1)
         my1(0,0) = oy*sy(0,0) &
            + sy(1,0)
         my1(1,0) = oy*sy(1,0) &
            + sy(2,0)
         my1(0,1) = oy*sy(0,1) &
            + sy(1,1)
         my1(1,1) = oy*sy(1,1) &
            + sy(2,1)
         my2(0,0) = oy*oy*sy(0,0) &
            + 2.0_dp*oy*sy(1,0) &
            + sy(2,0)
         my2(1,0) = oy*oy*sy(1,0) &
            + 2.0_dp*oy*sy(2,0) &
            + sy(3,0)
         my2(0,1) = oy*oy*sy(0,1) &
            + 2.0_dp*oy*sy(1,1) &
            + sy(2,1)
         my2(1,1) = oy*oy*sy(1,1) &
            + 2.0_dp*oy*sy(2,1) &
            + sy(3,1)
         my3(0,0) = oy*oy*oy*sy(0,0) &
            + 3.0_dp*oy*oy*sy(1,0) &
            + 3.0_dp*oy*sy(2,0) &
            + sy(3,0)
         my3(1,0) = oy*oy*oy*sy(1,0) &
            + 3.0_dp*oy*oy*sy(2,0) &
            + 3.0_dp*oy*sy(3,0) &
            + sy(4,0)
         my3(0,1) = oy*oy*oy*sy(0,1) &
            + 3.0_dp*oy*oy*sy(1,1) &
