         mout(6,36) = mout(6,36) + cc*sx(0,1)*my1(0,1)*mz2(1,0)
         mout(7,36) = mout(7,36) + cc*sx(1,1)*my1(0,0)*mz2(0,1)
         mout(8,36) = mout(8,36) + cc*sx(0,1)*my1(1,0)*mz2(0,1)
         mout(9,36) = mout(9,36) + cc*sx(0,1)*my1(0,0)*mz2(1,1)
         mout(10,36) = mout(10,36) + cc*sx(1,0)*my1(0,2)*mz2(0,0)
         mout(11,36) = mout(11,36) + cc*sx(0,0)*my1(1,2)*mz2(0,0)
         mout(12,36) = mout(12,36) + cc*sx(0,0)*my1(0,2)*mz2(1,0)
         mout(13,36) = mout(13,36) + cc*sx(1,0)*my1(0,1)*mz2(0,1)
         mout(14,36) = mout(14,36) + cc*sx(0,0)*my1(1,1)*mz2(0,1)
         mout(15,36) = mout(15,36) + cc*sx(0,0)*my1(0,1)*mz2(1,1)
         mout(16,36) = mout(16,36) + cc*sx(1,0)*my1(0,0)*mz2(0,2)
         mout(17,36) = mout(17,36) + cc*sx(0,0)*my1(1,0)*mz2(0,2)
         mout(18,36) = mout(18,36) + cc*sx(0,0)*my1(0,0)*mz2(1,2)
         mout(1,37) = mout(1,37) + cc*mx1(1,2)*sy(0,0)*mz2(0,0)
         mout(2,37) = mout(2,37) + cc*mx1(0,2)*sy(1,0)*mz2(0,0)
         mout(3,37) = mout(3,37) + cc*mx1(0,2)*sy(0,0)*mz2(1,0)
         mout(4,37) = mout(4,37) + cc*mx1(1,1)*sy(0,1)*mz2(0,0)
         mout(5,37) = mout(5,37) + cc*mx1(0,1)*sy(1,1)*mz2(0,0)
         mout(6,37) = mout(6,37) + cc*mx1(0,1)*sy(0,1)*mz2(1,0)
         mout(7,37) = mout(7,37) + cc*mx1(1,1)*sy(0,0)*mz2(0,1)
         mout(8,37) = mout(8,37) + cc*mx1(0,1)*sy(1,0)*mz2(0,1)
         mout(9,37) = mout(9,37) + cc*mx1(0,1)*sy(0,0)*mz2(1,1)
         mout(10,37) = mout(10,37) + cc*mx1(1,0)*sy(0,2)*mz2(0,0)
         mout(11,37) = mout(11,37) + cc*mx1(0,0)*sy(1,2)*mz2(0,0)
         mout(12,37) = mout(12,37) + cc*mx1(0,0)*sy(0,2)*mz2(1,0)
         mout(13,37) = mout(13,37) + cc*mx1(1,0)*sy(0,1)*mz2(0,1)
         mout(14,37) = mout(14,37) + cc*mx1(0,0)*sy(1,1)*mz2(0,1)
         mout(15,37) = mout(15,37) + cc*mx1(0,0)*sy(0,1)*mz2(1,1)
         mout(16,37) = mout(16,37) + cc*mx1(1,0)*sy(0,0)*mz2(0,2)
         mout(17,37) = mout(17,37) + cc*mx1(0,0)*sy(1,0)*mz2(0,2)
         mout(18,37) = mout(18,37) + cc*mx1(0,0)*sy(0,0)*mz2(1,2)
         mout(1,38) = mout(1,38) + cc*sx(1,2)*my1(0,0)*mz2(0,0)
         mout(2,38) = mout(2,38) + cc*sx(0,2)*my1(1,0)*mz2(0,0)
         mout(3,38) = mout(3,38) + cc*sx(0,2)*my1(0,0)*mz2(1,0)
         mout(4,38) = mout(4,38) + cc*sx(1,1)*my1(0,1)*mz2(0,0)
         mout(5,38) = mout(5,38) + cc*sx(0,1)*my1(1,1)*mz2(0,0)
         mout(6,38) = mout(6,38) + cc*sx(0,1)*my1(0,1)*mz2(1,0)
         mout(7,38) = mout(7,38) + cc*sx(1,1)*my1(0,0)*mz2(0,1)
         mout(8,38) = mout(8,38) + cc*sx(0,1)*my1(1,0)*mz2(0,1)
         mout(9,38) = mout(9,38) + cc*sx(0,1)*my1(0,0)*mz2(1,1)
         mout(10,38) = mout(10,38) + cc*sx(1,0)*my1(0,2)*mz2(0,0)
         mout(11,38) = mout(11,38) + cc*sx(0,0)*my1(1,2)*mz2(0,0)
         mout(12,38) = mout(12,38) + cc*sx(0,0)*my1(0,2)*mz2(1,0)
         mout(13,38) = mout(13,38) + cc*sx(1,0)*my1(0,1)*mz2(0,1)
         mout(14,38) = mout(14,38) + cc*sx(0,0)*my1(1,1)*mz2(0,1)
         mout(15,38) = mout(15,38) + cc*sx(0,0)*my1(0,1)*mz2(1,1)
         mout(16,38) = mout(16,38) + cc*sx(1,0)*my1(0,0)*mz2(0,2)
         mout(17,38) = mout(17,38) + cc*sx(0,0)*my1(1,0)*mz2(0,2)
         mout(18,38) = mout(18,38) + cc*sx(0,0)*my1(0,0)*mz2(1,2)
         mout(1,39) = mout(1,39) + cc*sx(1,2)*sy(0,0)*mz3(0,0)
         mout(2,39) = mout(2,39) + cc*sx(0,2)*sy(1,0)*mz3(0,0)
         mout(3,39) = mout(3,39) + cc*sx(0,2)*sy(0,0)*mz3(1,0)
         mout(4,39) = mout(4,39) + cc*sx(1,1)*sy(0,1)*mz3(0,0)
         mout(5,39) = mout(5,39) + cc*sx(0,1)*sy(1,1)*mz3(0,0)
         mout(6,39) = mout(6,39) + cc*sx(0,1)*sy(0,1)*mz3(1,0)
         mout(7,39) = mout(7,39) + cc*sx(1,1)*sy(0,0)*mz3(0,1)
         mout(8,39) = mout(8,39) + cc*sx(0,1)*sy(1,0)*mz3(0,1)
         mout(9,39) = mout(9,39) + cc*sx(0,1)*sy(0,0)*mz3(1,1)
         mout(10,39) = mout(10,39) + cc*sx(1,0)*sy(0,2)*mz3(0,0)
         mout(11,39) = mout(11,39) + cc*sx(0,0)*sy(1,2)*mz3(0,0)
         mout(12,39) = mout(12,39) + cc*sx(0,0)*sy(0,2)*mz3(1,0)
         mout(13,39) = mout(13,39) + cc*sx(1,0)*sy(0,1)*mz3(0,1)
         mout(14,39) = mout(14,39) + cc*sx(0,0)*sy(1,1)*mz3(0,1)
         mout(15,39) = mout(15,39) + cc*sx(0,0)*sy(0,1)*mz3(1,1)
         mout(16,39) = mout(16,39) + cc*sx(1,0)*sy(0,0)*mz3(0,2)
         mout(17,39) = mout(17,39) + cc*sx(0,0)*sy(1,0)*mz3(0,2)
         mout(18,39) = mout(18,39) + cc*sx(0,0)*sy(0,0)*mz3(1,2)
      end do
      end do
   end subroutine mult_12


   pure subroutine mult_20(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                 orig, mout)
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3), orig(3)
      real(dp), intent(out) :: mout(6,39)

      integer  :: ip, jp, k, ic
      real(dp) :: al, bet, zeta, oo2z, xi, cc
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: abx, aby, abz, e0x, e0y, e0z, ox, oy, oz
      real(dp) :: sx(0:5,0:2)
      real(dp) :: sy(0:5,0:2)
      real(dp) :: sz(0:5,0:2)
      real(dp) :: mx1(0:2,0:0), my1(0:2,0:0), mz1(0:2,0:0)
      real(dp) :: mx2(0:2,0:0), my2(0:2,0:0), mz2(0:2,0:0)
      real(dp) :: mx3(0:2,0:0), my3(0:2,0:0), mz3(0:2,0:0)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      ox = ra(1) - orig(1); oy = ra(2) - orig(2); oz = ra(3) - orig(3)

      do ic = 1, 39
         do k = 1, 6
            mout(k, ic) = 0.0_dp
         end do
      end do

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)
         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)
         e0x = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abx*abx)
         e0y = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*aby*aby)
         e0z = sqrt(3.14159265358979323846_dp/zeta)*exp(-xi*abz*abz)

         sx(0,0) = e0x
         sx(1,0) = pax*sx(0,0)
         sx(2,0) = pax*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(3,0) = pax*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(4,0) = pax*sx(3,0) + 3.0_dp*oo2z*sx(2,0)
         sx(5,0) = pax*sx(4,0) + 4.0_dp*oo2z*sx(3,0)
         sx(0,1) = pbx*sx(0,0)
         sx(1,1) = pbx*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(2,1) = pbx*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(3,1) = pbx*sx(3,0) + 3.0_dp*oo2z*sx(2,0)
         sx(4,1) = pbx*sx(4,0) + 4.0_dp*oo2z*sx(3,0)
         sx(5,1) = pbx*sx(5,0) + 5.0_dp*oo2z*sx(4,0)
         sx(0,2) = pbx*sx(0,1) + 1.0_dp*oo2z*sx(0,0)
         sx(1,2) = pbx*sx(1,1) + 1.0_dp*oo2z*sx(0,1) + 1.0_dp*oo2z*sx(1,0)
         sx(2,2) = pbx*sx(2,1) + 2.0_dp*oo2z*sx(1,1) + 1.0_dp*oo2z*sx(2,0)
         sx(3,2) = pbx*sx(3,1) + 3.0_dp*oo2z*sx(2,1) + 1.0_dp*oo2z*sx(3,0)
         sx(4,2) = pbx*sx(4,1) + 4.0_dp*oo2z*sx(3,1) + 1.0_dp*oo2z*sx(4,0)
         sx(5,2) = pbx*sx(5,1) + 5.0_dp*oo2z*sx(4,1) + 1.0_dp*oo2z*sx(5,0)
         sy(0,0) = e0y
         sy(1,0) = pay*sy(0,0)
         sy(2,0) = pay*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(3,0) = pay*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(4,0) = pay*sy(3,0) + 3.0_dp*oo2z*sy(2,0)
         sy(5,0) = pay*sy(4,0) + 4.0_dp*oo2z*sy(3,0)
         sy(0,1) = pby*sy(0,0)
         sy(1,1) = pby*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(2,1) = pby*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(3,1) = pby*sy(3,0) + 3.0_dp*oo2z*sy(2,0)
         sy(4,1) = pby*sy(4,0) + 4.0_dp*oo2z*sy(3,0)
         sy(5,1) = pby*sy(5,0) + 5.0_dp*oo2z*sy(4,0)
         sy(0,2) = pby*sy(0,1) + 1.0_dp*oo2z*sy(0,0)
         sy(1,2) = pby*sy(1,1) + 1.0_dp*oo2z*sy(0,1) + 1.0_dp*oo2z*sy(1,0)
         sy(2,2) = pby*sy(2,1) + 2.0_dp*oo2z*sy(1,1) + 1.0_dp*oo2z*sy(2,0)
         sy(3,2) = pby*sy(3,1) + 3.0_dp*oo2z*sy(2,1) + 1.0_dp*oo2z*sy(3,0)
         sy(4,2) = pby*sy(4,1) + 4.0_dp*oo2z*sy(3,1) + 1.0_dp*oo2z*sy(4,0)
         sy(5,2) = pby*sy(5,1) + 5.0_dp*oo2z*sy(4,1) + 1.0_dp*oo2z*sy(5,0)
         sz(0,0) = e0z
         sz(1,0) = paz*sz(0,0)
         sz(2,0) = paz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(3,0) = paz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(4,0) = paz*sz(3,0) + 3.0_dp*oo2z*sz(2,0)
         sz(5,0) = paz*sz(4,0) + 4.0_dp*oo2z*sz(3,0)
         sz(0,1) = pbz*sz(0,0)
         sz(1,1) = pbz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(2,1) = pbz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(3,1) = pbz*sz(3,0) + 3.0_dp*oo2z*sz(2,0)
         sz(4,1) = pbz*sz(4,0) + 4.0_dp*oo2z*sz(3,0)
         sz(5,1) = pbz*sz(5,0) + 5.0_dp*oo2z*sz(4,0)
         sz(0,2) = pbz*sz(0,1) + 1.0_dp*oo2z*sz(0,0)
         sz(1,2) = pbz*sz(1,1) + 1.0_dp*oo2z*sz(0,1) + 1.0_dp*oo2z*sz(1,0)
         sz(2,2) = pbz*sz(2,1) + 2.0_dp*oo2z*sz(1,1) + 1.0_dp*oo2z*sz(2,0)
         sz(3,2) = pbz*sz(3,1) + 3.0_dp*oo2z*sz(2,1) + 1.0_dp*oo2z*sz(3,0)
         sz(4,2) = pbz*sz(4,1) + 4.0_dp*oo2z*sz(3,1) + 1.0_dp*oo2z*sz(4,0)
         sz(5,2) = pbz*sz(5,1) + 5.0_dp*oo2z*sz(4,1) + 1.0_dp*oo2z*sz(5,0)

         mx1(0,0) = ox*sx(0,0) &
            + sx(1,0)
         mx1(1,0) = ox*sx(1,0) &
            + sx(2,0)
         mx1(2,0) = ox*sx(2,0) &
            + sx(3,0)
         mx2(0,0) = ox*ox*sx(0,0) &
            + 2.0_dp*ox*sx(1,0) &
            + sx(2,0)
         mx2(1,0) = ox*ox*sx(1,0) &
            + 2.0_dp*ox*sx(2,0) &
            + sx(3,0)
         mx2(2,0) = ox*ox*sx(2,0) &
            + 2.0_dp*ox*sx(3,0) &
            + sx(4,0)
         mx3(0,0) = ox*ox*ox*sx(0,0) &
            + 3.0_dp*ox*ox*sx(1,0) &
            + 3.0_dp*ox*sx(2,0) &
            + sx(3,0)
         mx3(1,0) = ox*ox*ox*sx(1,0) &
            + 3.0_dp*ox*ox*sx(2,0) &
            + 3.0_dp*ox*sx(3,0) &
            + sx(4,0)
         mx3(2,0) = ox*ox*ox*sx(2,0) &
            + 3.0_dp*ox*ox*sx(3,0) &
            + 3.0_dp*ox*sx(4,0) &
            + sx(5,0)
         my1(0,0) = oy*sy(0,0) &
            + sy(1,0)
         my1(1,0) = oy*sy(1,0) &
            + sy(2,0)
         my1(2,0) = oy*sy(2,0) &
            + sy(3,0)
         my2(0,0) = oy*oy*sy(0,0) &
            + 2.0_dp*oy*sy(1,0) &
            + sy(2,0)
         my2(1,0) = oy*oy*sy(1,0) &
            + 2.0_dp*oy*sy(2,0) &
            + sy(3,0)
         my2(2,0) = oy*oy*sy(2,0) &
            + 2.0_dp*oy*sy(3,0) &
            + sy(4,0)
         my3(0,0) = oy*oy*oy*sy(0,0) &
            + 3.0_dp*oy*oy*sy(1,0) &
            + 3.0_dp*oy*sy(2,0) &
            + sy(3,0)
         my3(1,0) = oy*oy*oy*sy(1,0) &
            + 3.0_dp*oy*oy*sy(2,0) &
            + 3.0_dp*oy*sy(3,0) &
            + sy(4,0)
         my3(2,0) = oy*oy*oy*sy(2,0) &
            + 3.0_dp*oy*oy*sy(3,0) &
            + 3.0_dp*oy*sy(4,0) &
            + sy(5,0)
         mz1(0,0) = oz*sz(0,0) &
            + sz(1,0)
         mz1(1,0) = oz*sz(1,0) &
            + sz(2,0)
         mz1(2,0) = oz*sz(2,0) &
            + sz(3,0)
         mz2(0,0) = oz*oz*sz(0,0) &
            + 2.0_dp*oz*sz(1,0) &
            + sz(2,0)
         mz2(1,0) = oz*oz*sz(1,0) &
            + 2.0_dp*oz*sz(2,0) &
            + sz(3,0)
         mz2(2,0) = oz*oz*sz(2,0) &
            + 2.0_dp*oz*sz(3,0) &
            + sz(4,0)
         mz3(0,0) = oz*oz*oz*sz(0,0) &
            + 3.0_dp*oz*oz*sz(1,0) &
            + 3.0_dp*oz*sz(2,0) &
            + sz(3,0)
         mz3(1,0) = oz*oz*oz*sz(1,0) &
            + 3.0_dp*oz*oz*sz(2,0) &
            + 3.0_dp*oz*sz(3,0) &
            + sz(4,0)
         mz3(2,0) = oz*oz*oz*sz(2,0) &
            + 3.0_dp*oz*oz*sz(3,0) &
            + 3.0_dp*oz*sz(4,0) &
            + sz(5,0)
         mout(1,1) = mout(1,1) + cc*mx1(2,0)*sy(0,0)*sz(0,0)
         mout(2,1) = mout(2,1) + cc*mx1(1,0)*sy(1,0)*sz(0,0)
         mout(3,1) = mout(3,1) + cc*mx1(1,0)*sy(0,0)*sz(1,0)
         mout(4,1) = mout(4,1) + cc*mx1(0,0)*sy(2,0)*sz(0,0)
         mout(5,1) = mout(5,1) + cc*mx1(0,0)*sy(1,0)*sz(1,0)
         mout(6,1) = mout(6,1) + cc*mx1(0,0)*sy(0,0)*sz(2,0)
         mout(1,2) = mout(1,2) + cc*sx(2,0)*my1(0,0)*sz(0,0)
         mout(2,2) = mout(2,2) + cc*sx(1,0)*my1(1,0)*sz(0,0)
         mout(3,2) = mout(3,2) + cc*sx(1,0)*my1(0,0)*sz(1,0)
         mout(4,2) = mout(4,2) + cc*sx(0,0)*my1(2,0)*sz(0,0)
         mout(5,2) = mout(5,2) + cc*sx(0,0)*my1(1,0)*sz(1,0)
         mout(6,2) = mout(6,2) + cc*sx(0,0)*my1(0,0)*sz(2,0)
         mout(1,3) = mout(1,3) + cc*sx(2,0)*sy(0,0)*mz1(0,0)
         mout(2,3) = mout(2,3) + cc*sx(1,0)*sy(1,0)*mz1(0,0)
         mout(3,3) = mout(3,3) + cc*sx(1,0)*sy(0,0)*mz1(1,0)
         mout(4,3) = mout(4,3) + cc*sx(0,0)*sy(2,0)*mz1(0,0)
         mout(5,3) = mout(5,3) + cc*sx(0,0)*sy(1,0)*mz1(1,0)
         mout(6,3) = mout(6,3) + cc*sx(0,0)*sy(0,0)*mz1(2,0)
         mout(1,4) = mout(1,4) + cc*mx2(2,0)*sy(0,0)*sz(0,0)
         mout(2,4) = mout(2,4) + cc*mx2(1,0)*sy(1,0)*sz(0,0)
         mout(3,4) = mout(3,4) + cc*mx2(1,0)*sy(0,0)*sz(1,0)
